use biome_rowan::{AstNode, AstNodeList, BatchMutationExt, TextRange, TextSize};
use biome_rule_options::no_jsx_leaked_dollar::NoJsxLeakedDollarOptions;

declare_lint_rule! {
    /// Disallow a stray `$` at the end of a JSX text node placed right before a JSX expression.
    ///
    /// When migrating a template literal to JSX, it is easy to keep the `$` that used to
    /// precede an interpolation (`${...}`). In JSX, that `$` is no longer part of the
    /// interpolation syntax and is rendered as plain text, which is almost never intended.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```jsx,expect_diagnostic
    /// <div>Hello ${name}</div>
    /// ```
    ///
    /// ### Valid
    ///
    /// ```jsx
    /// <div>Hello {name}</div>
    /// ```
    ///
    /// A lone `$` before a single expression is treated as intentional, for example to
    /// render a currency value:
    ///
    /// ```jsx
    /// <div>${price}</div>
    /// ```
    ///
    pub NoJsxLeakedDollar {
        version: "next",
        name: "noJsxLeakedDollar",
        language: "jsx",
        recommended: false,
        fix_kind: FixKind::Unsafe,
    }
}

impl Rule for NoJsxLeakedDollar {
    type Query = Ast<JsxText>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = NoJsxLeakedDollarOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let node = ctx.query();
        let token = node.value_token().ok()?;
        let text = token.text();

        // The text node must end with a `$` character.
        if !text.ends_with('$') {
            return None;
        }

        // The immediately following sibling must be a JSX expression child.
        let next_sibling = node.syntax().next_sibling()?;
        if !JsxExpressionChild::can_cast(next_sibling.kind()) {
            return None;
        }

        // A lone `$` before a single expression (e.g. `<div>${price}</div>`) is treated as
        // intentional, such as displaying a currency value.
        if text.trim() == "$" {
            if let Some(list) = node
                .syntax()
                .parent()
                .and_then(biome_js_syntax::JsxChildList::cast)
            {
                if list.len() == 2 {
                    return None;
                }
            }
        }

        Some(())
    }

    fn diagnostic(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<RuleDiagnostic> {
        let node = ctx.query();
        let token = node.value_token().ok()?;
        // Point at the trailing `$` character.
        let end = token.text_range().end();
        let dollar_range = TextRange::new(end - TextSize::from(1), end);

        Some(
            RuleDiagnostic::new(
                rule_category!(),
                dollar_range,
                markup! {
                    "Possible unintentional '$' before a JSX expression."
                },
            )
            .note(markup! {
                "This '$' will be rendered as text. Remove the '$' from the text node or add a suppression if it is intentional."
            }),
        )
    }

    fn action(ctx: &RuleContext<Self>, _state: &Self::State) -> Option<JsRuleAction> {
        let node = ctx.query();
        let token = node.value_token().ok()?;
        let text = token.text();

        // Remove only the trailing `$` character.
        let new_text = &text[..text.len() - 1];
        let new_jsx_text = AnyJsxChild::JsxText(make::jsx_text(JsSyntaxToken::new_detached(
            JsSyntaxKind::JSX_TEXT,
            new_text,
            [],
            [],
        )));

        let mut mutation = ctx.root().begin();
        mutation.replace_node(AnyJsxChild::from(node.clone()), new_jsx_text);

        Some(JsRuleAction::new(
            ctx.metadata().action_category(ctx.category(), ctx.group()),
            ctx.metadata().applicability(),
            markup! { "Remove dollar sign." }.to_owned(),
            mutation,
        ))
    }
}
